#!/usr/bin/env bash
# Run only inside an officially permitted PC2 container environment.
set -euo pipefail
umask 077
cd "$(dirname "$(readlink -f "$0")")"
mode="${1:-preflight}"
if [[ $# -gt 0 ]]; then shift; fi
if [[ -r image.env ]]; then
    # File format is generated by CI, never evaluated as shell code.
    image="$(sed -n 's/^ELDERCARE_IMAGE=//p' image.env)"
else
    image=eldercare-x2:dev
fi
image="${ELDERCARE_IMAGE:-$image}"
engine="${CONTAINER_ENGINE:-}"
if [[ -z "$engine" ]]; then
    if command -v podman >/dev/null; then engine=podman
    elif command -v docker >/dev/null; then engine=docker
    else printf '%s\n' 'No permitted Podman/Docker runtime found; do not install it on the robot automatically.' >&2; exit 10
    fi
fi
case "$engine" in podman|docker) ;; *) echo 'CONTAINER_ENGINE must be podman or docker' >&2; exit 11;; esac
case "$mode" in
    load)
        sha256sum -c SHA256SUMS
        exec "$engine" load -i eldercare-x2-arm64.tar.gz
        ;;
    dependencies|dashboard|preflight|full-agent|mic-probe|asr-probe|asr-diagnostic|tts-probe|motion-diagnostic|motion-probe) ;;
    *) echo 'Usage: bash run.sh load|dependencies|preflight|full-agent|dashboard|mic-probe|asr-probe|asr-diagnostic|tts-probe|motion-diagnostic|motion-probe' >&2; exit 12;;
esac
if [[ "$mode" == full-agent && "${X2_ONLY_VOICE_CONFIRMED:-0}" != 1 ]]; then
    echo 'First confirm native only_voice and stable standing; export X2_ONLY_VOICE_CONFIRMED=1 for this session.' >&2
    exit 23
fi
mkdir -p state/logs
options=(--rm --init --network host --ipc host --read-only
    --tmpfs /tmp:rw,nosuid,size=256m,mode=1777
    --user "$(id -u):$(id -g)"
    --mount "type=bind,src=$PWD/state,dst=/var/lib/eldercare"
    -e "X2_ONLY_VOICE_CONFIRMED=${X2_ONLY_VOICE_CONFIRMED:-0}"
    -e "ROS_DOMAIN_ID=${ROS_DOMAIN_ID:-0}")
if [[ -t 0 ]]; then options+=(-it); fi
if [[ "$engine" == podman ]]; then options+=(--userns keep-id); fi
if [[ -r .env ]]; then
    options+=(--mount "type=bind,src=$PWD/.env,dst=/opt/eldercare/.env,readonly")
elif [[ "$mode" == full-agent || "$mode" == asr-* || "$mode" == tts-probe ]]; then
    echo 'Configure the private .env beside run.sh first.' >&2; exit 24
fi
if [[ "$mode" != dashboard && "$mode" != dependencies ]]; then
    sdk="${X2_SDK_DIR:-/home/agi/aimdk}"
    [[ -r "$sdk/install/local_setup.bash" ]] || { echo 'Matching SDK install is not readable.' >&2; exit 22; }
    options+=(--mount "type=bind,src=$sdk,dst=/home/agi/aimdk,readonly")
    # Match the official PC2 model: host ROS, SDK, shared libraries and DDS.
    if [[ -d /opt/ros ]]; then options+=(--mount type=bind,src=/opt/ros,dst=/opt/ros,readonly); fi
    if [[ -d /usr/lib/aarch64-linux-gnu ]]; then
        options+=(--mount type=bind,src=/usr/lib/aarch64-linux-gnu,dst=/host-libs/aarch64-linux-gnu,readonly
            -e LD_LIBRARY_PATH=/opt/ros/humble/lib:/host-libs/aarch64-linux-gnu)
    fi
    dds="${X2_DDS_CONFIG:-/home/agi/.aima/env/ros_dds_configuration.xml}"
    if [[ -r "$dds" ]]; then
        options+=(--mount "type=bind,src=$dds,dst=/etc/ros_dds_configuration.xml,readonly"
            -e FASTRTPS_DEFAULT_PROFILES_FILE=/etc/ros_dds_configuration.xml)
    fi
    if [[ -r /home/agi/.aima/env/bashrc ]]; then
        while IFS= read -r line; do
            if [[ "$line" =~ ^export\ (AGIBOT_[A-Z_]+)=\'(.*)\'$ ]]; then
                options+=(-e "${BASH_REMATCH[1]}=${BASH_REMATCH[2]}")
            fi
        done < /home/agi/.aima/env/bashrc
    fi
    if [[ -n "${RMW_IMPLEMENTATION:-}" ]]; then options+=(-e "RMW_IMPLEMENTATION=$RMW_IMPLEMENTATION"); fi
fi
exec "$engine" run "${options[@]}" "$image" "$mode" "$@"
